use std::env;
use std::num::IntErrorKind;
use std::process;

const DEFAULT_COUNT: i32 = 15;
const COUNT_FLAG: &str = "--a";

pub fn parse_count() -> i32 {
    let args: Vec<String> = env::args().collect();
    let mut count = DEFAULT_COUNT;

    if args.len() > 1 && args[1] == COUNT_FLAG {
        let raw_value = match args.get(2) {
            Some(value) => value,
            None => abort_with(
                "terminate called after throwing an instance of 'std::logic_error'\n  what():  basic_string::_S_construct null not valid",
            ),
        };

        count = parse_i32_like_stoi(raw_value);
    }

    count
}

fn parse_i32_like_stoi(raw_value: &str) -> i32 {
    match raw_value.parse::<i32>() {
        Ok(value) => value,
        Err(error) => match error.kind() {
            IntErrorKind::PosOverflow | IntErrorKind::NegOverflow => abort_with(
                "terminate called after throwing an instance of 'std::out_of_range'\n  what():  stoi",
            ),
            _ => abort_with(
                "terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoi",
            ),
        },
    }
}

fn abort_with(message: &str) -> ! {
    eprintln!("{message}");
    process::abort();
}

