use std::collections::HashMap;
use std::hash::Hash;

pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            inner: HashMap::new(),
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> Option<V> {
        self.inner.insert(entry.0, entry.1)
    }

    pub fn equal_range<'a>(&'a self, key: &K) -> EqualRange<'a, K, V> {
        EqualRange {
            item: self.inner.get_key_value(key),
            consumed: false,
        }
    }
}

pub struct EqualRange<'a, K, V> {
    item: Option<(&'a K, &'a V)>,
    consumed: bool,
}

impl<'a, K, V> Iterator for EqualRange<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        if self.consumed {
            None
        } else {
            self.consumed = true;
            self.item
        }
    }
}

